Both Product and Bundle implement IItem. A Bundle sums its children, which can be bundles themselves, and then applies its own discount.
```csharp
interface IItem { decimal Price(); }
class Product(decimal cost) : IItem { public decimal Price() => cost; }
class Bundle(decimal discount) : IItem {
    private readonly List<IItem> _items = new();
    public void Add(IItem item) => _items.Add(item);
    public decimal Price() => _items.Sum(i => i.Price()) * (1 - discount);
}
```

Keep two stacks. Execute pushes onto undo and clears redo; Undo pops, calls Unexecute and pushes onto redo; Redo does the reverse.
```csharp
interface ICommand { void Execute(); void Undo(); }
class History {
    private readonly Stack<ICommand> _undo = new(), _redo = new();
    public void Run(ICommand c) { c.Execute(); _undo.Push(c); _redo.Clear(); }
    public void Undo() { if (_undo.TryPop(out var c)) { c.Undo(); _redo.Push(c); } }
    public void Redo() { if (_redo.TryPop(out var c)) { c.Execute(); _undo.Push(c); } }
}
```

The ordering key changes when the score changes, so remove the old tuple before adding the new one.
```csharp
class Leaderboard {
    private readonly Dictionary<string, int> _scores = new();
    private readonly SortedSet<(int Score, string Id)> _set = new(Comparer<(int Score, string Id)>.Create(
        (a, b) => a.Score != b.Score ? b.Score.CompareTo(a.Score) : string.CompareOrdinal(a.Id, b.Id)));
    public void AddScore(string id, int delta) {
        if (_scores.TryGetValue(id, out var old)) _set.Remove((old, id));
        _scores[id] = old + delta;
        _set.Add((old + delta, id));
    }
    public IEnumerable<(int Score, string Id)> Top(int k) => _set.Take(k);
}
```

Each user's posts are already in time order, so merge K sorted lists with a max-heap (the LeetCode Design Twitter problem).
```csharp
public IList<Post> GetNewsFeed(int userId, int limit = 10) {
    var pq = new PriorityQueue<(List<Post> list, int idx), long>();
    foreach (var uid in _follows.Following(userId).Append(userId))
        if (_posts.TryGetValue(uid, out var l) && l.Count > 0)
            pq.Enqueue((l, l.Count - 1), -l[^1].Timestamp);
    var feed = new List<Post>();
    while (feed.Count < limit && pq.TryDequeue(out var cur, out _)) {
        feed.Add(cur.list[cur.idx]);
        if (cur.idx > 0) pq.Enqueue((cur.list, cur.idx - 1), -cur.list[cur.idx - 1].Timestamp);
    }
    return feed;
}
```

Every state returns the next state; events that are not allowed throw by default.
```csharp
abstract class MessageState {
    public virtual MessageState OnServerAck() => throw new InvalidOperationException();
    public virtual MessageState OnDelivered() => throw new InvalidOperationException();
    public virtual MessageState OnRead() => throw new InvalidOperationException();
}
class Pending : MessageState { public override MessageState OnServerAck() => new Sent(); }
class Sent : MessageState {
    public override MessageState OnDelivered() => new Delivered();
    public override MessageState OnRead() => new Read();
}
class Delivered : MessageState { public override MessageState OnRead() => new Read(); }
class Read : MessageState { }
```

SetNext returns the next handler so a chain can be built fluently: validate.SetNext(meta).SetNext(transcode).
```csharp
abstract class VideoHandler {
    private VideoHandler? _next;
    public VideoHandler SetNext(VideoHandler next) { _next = next; return next; }
    public virtual Task HandleAsync(VideoJob job) => _next?.HandleAsync(job) ?? Task.CompletedTask;
}
class ValidateHandler : VideoHandler {
    public override Task HandleAsync(VideoJob job) {
        if (job.SizeBytes > 10L * 1024 * 1024 * 1024) throw new InvalidOperationException("File too large");
        return base.HandleAsync(job);
    }
}
