Keep stops above and below the current floor in two sorted sets; serve everything in the current direction, then reverse.
```csharp
class Elevator {
    public int Floor { get; private set; }
    public Direction Dir { get; private set; } = Direction.Idle;
    private readonly SortedSet<int> _up = new(), _down = new();
    public void AddStop(int f) { if (f >= Floor) _up.Add(f); else _down.Add(f); }
    public int? NextStop() => Dir != Direction.Down
        ? (_up.Count > 0 ? _up.Min : _down.Count > 0 ? _down.Max : (int?)null)
        : (_down.Count > 0 ? _down.Max : _up.Count > 0 ? _up.Min : (int?)null);
}
```

