Round down to paise and give the leftover to one participant, so the splits always add up exactly to the total.
```csharp
public interface ISplitStrategy {
    Dictionary<string, decimal> Split(decimal total, IReadOnlyList<string> users, IReadOnlyList<decimal>? values);
}
public class EqualSplit : ISplitStrategy {
    public Dictionary<string, decimal> Split(decimal total, IReadOnlyList<string> users, IReadOnlyList<decimal>? values) {
        var share = Math.Round(total / users.Count, 2, MidpointRounding.ToZero);
        var result = users.ToDictionary(u => u, u => share);
        result[users[0]] += total - share * users.Count;
        return result;
    }
}
```

ParkingLot coordinates; allocation, pricing and time are injected.
```csharp
public Ticket Park(Vehicle v) {
    var spot = _allocator.FindSpot(_floors, v.Type) ?? throw new InvalidOperationException("Lot full");
    spot.Assign(v);
    var ticket = new Ticket(Guid.NewGuid(), v, spot, _clock.GetUtcNow());
    _active[ticket.Id] = ticket;
    return ticket;
}
public decimal Unpark(Guid ticketId) {
    if (!_active.Remove(ticketId, out var t)) throw new KeyNotFoundException();
    t.Spot.Release();
    return _pricing.Calculate(t.Spot.Type, t.EntryTime, _clock.GetUtcNow());
}
